This is a complete solution using **Qt5**.

### Important Prerequisite: Excel Handling
Qt **does not** have built-in support for reading/writing binary Excel formats (`.xls`, `.xlsx`). To do this in C++, you need an external library. The standard open-source choice for Qt projects is **QtXlsx**.

1.  **Download QtXlsx:** Get it from [GitHub - QtExcel/QXlsx](https://github.com/QtExcel/QXlsx).
2.  **Add to Project:** You usually add the source files to your project or link the library.
3.  **Limitation:** QtXlsx primarily supports `.xlsx`. Support for old `.xls` files requires different libraries (like `libxl`), which are often commercial. This code focuses on `.xlsx`.

### Project Structure
You will need three files: `ExcelConverter.pro`, `main.cpp`, `mainwindow.h`, and `mainwindow.cpp`.

### 1. The Project File (`ExcelConverter.pro`)
This tells Qt how to build the application and link the necessary modules.

```qmake
QT       += core gui widgets

greaterThan(QT_MAJOR_VERSION, 4): QT += widgets

TARGET = ExcelConverter
TEMPLATE = app

# You need to add the path to the QXlsx library here
# For example, if you cloned QXlsx into a folder named 'QXlsx' next to this project:
include(../QXlsx/QXlsx/QXlsx.pri)

SOURCES += \
    main.cpp \
    mainwindow.cpp

HEADERS += \
    mainwindow.h
```

### 2. The Header File (`mainwindow.h`)
Defines the GUI class and the conversion logic.

```cpp
#ifndef MAINWINDOW_H
#define MAINWINDOW_H

#include <QMainWindow>
#include <QString>
#include <QDir>

QT_BEGIN_NAMESPACE
namespace Ui { class MainWindow; }
QT_END_NAMESPACE

class MainWindow : public QMainWindow
{
    Q_OBJECT

public:
    MainWindow(QWidget *parent = nullptr);
    ~MainWindow();

private slots:
    void onSelectDirectory();
    void convertDirectory(const QString &path);

private:
    // Helper to convert a single Excel file to CSV
    bool convertExcelToCsv(const QString &xlsxPath, const QString &csvPath);

    // Helper to escape CSV special characters
    QString escapeCsvField(const QString &field);
};

#endif // MAINWINDOW_H
```

### 3. The Implementation File (`mainwindow.cpp`)
Contains the GUI setup and the file processing logic.

```cpp
#include "mainwindow.h"
#include <QApplication>
#include <QFileDialog>
#include <QLabel>
#include <QPushButton>
#include <QVBoxLayout>
#include <QMessageBox>
#include <QDir>
#include <QFileInfo>
#include <QTextStream>
#include <QVector>

// Include the QtXlsx library
#include <QXlsx/QXlsx>

MainWindow::MainWindow(QWidget *parent)
    : QMainWindow(parent)
{
    // Setup central widget and layout manually (no .ui file needed)
    QWidget *centralWidget = new QWidget(this);
    setCentralWidget(centralWidget);
    QVBoxLayout *layout = new QVBoxLayout(centralWidget);

    // Label for instructions
    QLabel *label = new QLabel("Select a directory containing Excel files (.xlsx)", this);
    label->setWordWrap(true);
    layout->addWidget(label);

    // Button to trigger selection
    QPushButton *btnSelect = new QPushButton("Select Directory", this);
    connect(btnSelect, &QPushButton::clicked, this, &MainWindow::onSelectDirectory);
    layout->addWidget(btnSelect);

    // Label to show status
    QLabel *statusLabel = new QLabel("Status: Waiting...", this);
    statusLabel->setObjectName("statusLabel");
    layout->addWidget(statusLabel);

    setWindowTitle("Excel to CSV Converter");
    resize(400, 200);
}

MainWindow::~MainWindow()
{
}

void MainWindow::onSelectDirectory()
{
    // Prompt user for a directory
    QString dirPath = QFileDialog::getExistingDirectory(this, tr("Open Directory"),
                                                        "/",
                                                        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

    if (dirPath.isEmpty()) {
        return; // User cancelled
    }

    // Update status
    findChild<QLabel*>("statusLabel")->setText("Status: Processing...");
    QApplication::processEvents(); // Refresh UI

    convertDirectory(dirPath);

    findChild<QLabel*>("statusLabel")->setText("Status: Finished!");
}

void MainWindow::convertDirectory(const QString &path)
{
    QDir dir(path);

    // Create output folder
    QString outputFolderName = "converted_csv";
    QString outputFolderPath = path + "/" + outputFolderName;

    if (!dir.mkdir(outputFolderName)) {
        QMessageBox::critical(this, "Error", "Could not create output folder.");
        return;
    }

    // Filter for Excel files
    // Note: QtXlsx primarily handles .xlsx. .xls requires different libraries.
    QStringList filters;
    filters << "*.xlsx"; 
    dir.setNameFilters(filters);
    dir.setFilter(QDir::Files);

    QFileInfoList fileList = dir.entryInfoList();

    if (fileList.isEmpty()) {
        QMessageBox::information(this, "Info", "No .xlsx files found in this directory.");
        return;
    }

    int successCount = 0;

    foreach (QFileInfo fileInfo, fileList) {
        QString inputFilePath = fileInfo.absoluteFilePath();
        QString outputFileName = fileInfo.baseName() + ".csv";
        QString outputFilePath = outputFolderPath + "/" + outputFileName;

        if (convertExcelToCsv(inputFilePath, outputFilePath)) {
            successCount++;
        }
    }

    QMessageBox::information(this, "Complete", 
                             QString("Conversion complete.\n%1 files converted to '%2'").arg(successCount).arg(outputFolderName));
}

bool MainWindow::convertExcelToCsv(const QString &xlsxPath, const QString &csvPath)
{
    // Load the Excel document using QtXlsx
    QXlsx::Document xlsx(xlsxPath);

    if (!xlsx.load()) {
        qWarning() << "Failed to load:" << xlsxPath;
        return false;
    }

    QFile file(csvPath);
    if (!file.open(QIODevice::WriteOnly | QIODevice::Text)) {
        qWarning() << "Failed to open CSV for writing:" << csvPath;
        return false;
    }

    QTextStream out(&file);
    // Set UTF-8 encoding for CSV
    out.setCodec("UTF-8"); 

    // QtXlsx works with Sheets. We will convert the first visible sheet.
    // For a robust app, you might iterate all sheets.
    xlsx.setCurrentSheet(1); 

    // Get dimensions
    int rowCnt = xlsx.dimension().rowCount();
    int colCnt = xlsx.dimension().columnCount();

    for (int row = 1; row <= rowCnt; ++row) {
        QStringList lineData;
        for (int col = 1; col <= colCnt; ++col) {
            QXlsx::Cell *cell = xlsx.cellAt(row, col);
            QString value;

            if (cell) {
                // Handle different cell types
                if (cell->dataType() == QXlsx::Cell::StringType) {
                    value = cell->value().toString();
                } else if (cell->dataType() == QXlsx::Cell::NumericType) {
                    value = QString::number(cell->value().toDouble());
                } else {
                    value = cell->value().toString();
                }
            }

            lineData.append(escapeCsvField(value));
        }
        out << lineData.join(",") << "\n";
    }

    file.close();
    return true;
}

QString MainWindow::escapeCsvField(const QString &field)
{
    // CSV RFC 4180 logic:
    // If field contains comma, newline, or double quote, wrap in quotes.
    // Double quotes inside the field must be escaped by doubling them.

    if (field.contains(",") || field.contains("\n") || field.contains("\"")) {
        QString escaped = field;
        escaped.replace("\"", "\"\"");
        return "\"" + escaped + "\"";
    }
    return field;
}
```

### 4. The Entry Point (`main.cpp`)
Standard Qt application bootstrap.

```cpp
#include "mainwindow.h"
#include <QApplication>

int main(int argc, char *argv[])
{
    QApplication a(argc, argv);
    MainWindow w;
    w.show();
    return a.exec();
}
```

### How to Build and Run

1.  **Install Qt5:** Ensure you have Qt5 installed (e.g., via the Official Qt Installer or package manager like `apt`/`brew`).
2.  **Get QtXlsx:**
    *   Clone the repository: `git clone https://github.com/QtExcel/QXlsx.git`
    *   Place it in a folder accessible to your project.
3.  **Configure `.pro`:** Update the `include(../QXlsx/QXlsx/QXlsx.pri)` line in the `.pro` file to point to the actual location of the `QXlsx.pri` file on your system.
4.  **Compile:**
    *   Open Qt Creator and open the `.pro` file.
    *   Click **Build** -> **Run**.
    *   Or via command line:
        ```bash
        qmake ExcelConverter.pro
        make
        ./ExcelConverter
        ```

### Key Features of this Code
1.  **GUI:** Uses `QFileDialog` for native directory picking.
2.  **Safety:** Creates a specific subfolder (`converted_csv`) so it doesn't overwrite original files.
3.  **CSV Compliance:** The `escapeCsvField` function ensures that if your Excel data contains commas or quotes, the resulting CSV remains valid and parseable.
4.  **Encoding:** Forces UTF-8 output, which is standard for modern CSV handling.
5.  **Error Handling:** Checks if files open correctly and reports status to the user via `QMessageBox`.

### Note on `.xls` (Old Excel Format)
The code above filters for `*.xlsx`. If you strictly need `*.xls` (Excel 97-2003), QtXlsx will not work. You would need to integrate a library like **LibXL** (commercial) or use a system call (`QProcess`) to invoke a tool like **LibreOffice** in headless mode:
`libreoffice --headless --convert-to csv file.xls`
For a pure C++ solution, `.xlsx` (Office Open XML) is the recommended standard.

