TARGET = ExcelConverter
TEMPLATE = app

# You need to add the path to the QXlsx library here
# For example, if you cloned QXlsx into a folder named 'QXlsx' next to this project:
include(../QXlsx/QXlsx/QXlsx.pri)

SOURCES += \
    main.cpp \
    mainwindow.cpp

HEADERS += \
