void MainWindow::onSelectDirectory()
{
    // Prompt user for a directory
    QString dirPath = QFileDialog::getExistingDirectory(this, tr("Open Directory"),
                                                        "/",
                                                        QFileDialog::ShowDirsOnly | QFileDialog::DontResolveSymlinks);

    if (dirPath.isEmpty()) {
        return; // User cancelled
    }

    // Update status
    findChild<QLabel*>("statusLabel")->setText("Status: Processing...");
    QApplication::processEvents(); // Refresh UI

    convertDirectory(dirPath);

    findChild<QLabel*>("statusLabel")->setText("Status: Finished!");
}

void MainWindow::convertDirectory(const QString &path)
{
    QDir dir(path);

    // Create output folder
    QString outputFolderName = "converted_csv";
    QString outputFolderPath = path + "/" + outputFolderName;

    if (!dir.mkdir(outputFolderName)) {
        QMessageBox::critical(this, "Error", "Could not create output folder.");
        return;
    }

    // Filter for Excel files
    // Note: QtXlsx primarily handles .xlsx. .xls requires different libraries.
    QStringList filters;
    filters << "*.xlsx"; 
    dir.setNameFilters(filters);
    dir.setFilter(QDir::Files);

    QFileInfoList fileList = dir.entryInfoList();

    if (fileList.isEmpty()) {
        QMessageBox::information(this, "Info", "No .xlsx files found in this directory.");
        return;
    }

    int successCount = 0;

    foreach (QFileInfo fileInfo, fileList) {
        QString inputFilePath = fileInfo.absoluteFilePath();
        QString outputFileName = fileInfo.baseName() + ".csv";
        QString outputFilePath = outputFolderPath + "/" + outputFileName;

        if (convertExcelToCsv(inputFilePath, outputFilePath)) {
            successCount++;
        }
    }

    QMessageBox::information(this, "Complete", 
                             QString("Conversion complete.\n%1 files converted to '%2'").arg(successCount).arg(outputFolderName));
}

bool MainWindow::convertExcelToCsv(const QString &xlsxPath, const QString &csvPath)
{
    // Load the Excel document using QtXlsx
    QXlsx::Document xlsx(xlsxPath);

    if (!xlsx.load()) {
        qWarning() << "Failed to load:" << xlsxPath;
        return false;
    }

    QFile file(csvPath);
    if (!file.open(QIODevice::WriteOnly | QIODevice::Text)) {
        qWarning() << "Failed to open CSV for writing:" << csvPath;
        return false;
    }

    QTextStream out(&file);
    // Set UTF-8 encoding for CSV
    out.setCodec("UTF-8"); 

    // QtXlsx works with Sheets. We will convert the first visible sheet.
    // For a robust app, you might iterate all sheets.
    xlsx.setCurrentSheet(1); 

    // Get dimensions
    int rowCnt = xlsx.dimension().rowCount();
    int colCnt = xlsx.dimension().columnCount();

    for (int row = 1; row <= rowCnt; ++row) {
        QStringList lineData;
        for (int col = 1; col <= colCnt; ++col) {
            QXlsx::Cell *cell = xlsx.cellAt(row, col);
            QString value;

            if (cell) {
                // Handle different cell types
                if (cell->dataType() == QXlsx::Cell::StringType) {
                    value = cell->value().toString();
                } else if (cell->dataType() == QXlsx::Cell::NumericType) {
                    value = QString::number(cell->value().toDouble());
                } else {
                    value = cell->value().toString();
                }
            }

            lineData.append(escapeCsvField(value));
        }
        out << lineData.join(",") << "\n";
    }

    file.close();
    return true;
}

QString MainWindow::escapeCsvField(const QString &field)
{
    // CSV RFC 4180 logic:
    // If field contains comma, newline, or double quote, wrap in quotes.
    // Double quotes inside the field must be escaped by doubling them.

    if (field.contains(",") || field.contains("\n") || field.contains("\"")) {
        QString escaped = field;
        escaped.replace("\"", "\"\"");
        return "\"" + escaped + "\"";
    }
    return field;
}
